package com.rikkeibank.identity.service;import com.rikkeibank.identity.domain.*;import com.rikkeibank.identity.repo.*;import org.junit.jupiter.api.Test;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.time.Duration;import java.util.Optional;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class AuthServiceTest{@Test void loginIssuesAccessAndRefreshTokens(){UserRepository users=mock(UserRepository.class);RefreshTokenRepository tokens=mock(RefreshTokenRepository.class);StringRedisTemplate redis=mock(StringRedisTemplate.class);var encoder=new BCryptPasswordEncoder(4);AppUser user=new AppUser("alice",encoder.encode("secret123"),AppUser.Role.CUSTOMER,"Alice",java.util.UUID.randomUUID());when(users.findByUsername("alice")).thenReturn(Optional.of(user));when(tokens.save(any())).thenAnswer(i->i.getArgument(0));AuthService service=new AuthService(users,tokens,encoder,redis,"0123456789012345678901234567890123456789",Duration.ofMinutes(15),Duration.ofDays(30));var pair=service.login("alice","secret123");assertThat(pair.accessToken()).isNotBlank();assertThat(pair.refreshToken()).isNotBlank();assertThat(pair.expiresIn()).isEqualTo(900);verify(tokens).save(any(RefreshToken.class));}}
